SELECT COUNT(DISTINCT b.pro_id)
    FROM tblmire_camp_mst AS a
        right JOIN tblmicp_program AS b
            ON a.PRO_ID = b.PRO_ID AND b.PRO_TG_TP != 'TEST'
        INNER JOIN tblmi_comm_cd AS c
            ON c.grp_id = 'COMST' and b.PRO_ST = c.CD_ID
        INNER JOIN tblmi_comm_cd AS e
            ON e.grp_id = 'TGTP' and b.PRO_TG_TP = e.cd_id

        a.usr_grp_cd = #{usr_grp_cd}
        -- AND b.pro_st = '04'
        AND b.pro_tg_tp NOT LIKE 'TEST%'

            AND b.pro_st = #{pro_st}


            and b.pro_nm like CONCAT('%', #{pro_nm},'%')


            and b.pro_tg_tp = #{pro_tg_tp}


            and b.pro_tp = #{pro_tp}


            and a.CAMP_CH = #{camp_ch}


            and b.min_start_dt  >= #{st_dt} 


            and b.min_start_dt  <= date_add(#{end_dt}, interval 1 day)

WITH T(pro_id) AS ( SELECT distinct(mst.pro_id) FROM tblmire_camp_mst AS mst INNER JOIN tblmicp_program AS prg ON mst.PRO_ID = prg.PRO_ID INNER JOIN tblmi_comm_cd AS com ON com.grp_id = 'COMST' AND prg.pro_st = com.cd_id INNER JOIN tblmi_comm_cd AS tg ON tg.grp_id = 'TGTP' AND prg.pro_tg_tp = tg.cd_id
mst.usr_grp_cd = #{usr_grp_cd} -- AND b.pro_st = '04' AND prg.pro_tg_tp NOT LIKE 'TEST%'
AND prg.pro_st = #{pro_st}
and prg.pro_nm like CONCAT('%', #{pro_nm},'%')
and mst.camp_nm like CONCAT('%', #{camp_nm},'%')
and prg.pro_tg_tp = #{pro_tg_tp}
and prg.pro_tp = #{pro_tp}
and (tg.usr_nm like CONCAT('%', #{usr_nm},'%') or tg.usr_log_id like CONCAT('%', #{usr_nm},'%'))
and mst.CAMP_CH = #{camp_ch}
and prg.min_start_dt >= #{st_dt}
and prg.min_start_dt <= date_add(#{end_dt}, interval 1 day)
ORDER BY mst.REG_DT DESC, mst.PRO_ID DESC
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}
) SELECT a.seq As seq ,b.PRO_ID AS pro_id , b.PRO_NM AS pro_nm , a.camp_id as camp_id , a.camp_nm as camp_nm , b.PRO_ST AS pro_st , b.min_start_dt AS start_dt , a.cont_id AS cont_id , c.cd_nm AS pro_st_nm , a.CAMP_CH AS camp_ch -- 채널 , a.TOTAL_CNT AS total_cnt , a.SUC_CNT AS suc_cnt , IFNULL(a.OPEN_CNT,0) AS open_cnt , IFNULL(a.CLICK_CNT,0) AS click_cnt FROM T INNER join tblmire_camp_mst AS a ON T.pro_id = a.PRO_ID INNER JOIN tblmicp_program AS b ON a.PRO_ID = b.PRO_ID AND b.PRO_TG_TP != 'TEST' INNER JOIN tblmi_comm_cd AS c ON c.grp_id = 'COMST' and b.PRO_ST = c.CD_ID INNER JOIN tblmi_comm_cd AS e ON e.grp_id = 'TGTP' and b.PRO_TG_TP = e.cd_id
a.usr_grp_cd = #{usr_grp_cd} -- AND b.pro_st = '04' AND b.pro_tg_tp NOT LIKE 'TEST%'
AND b.pro_st = #{pro_st}
and b.pro_nm like CONCAT('%', #{pro_nm},'%')
and a.camp_nm like CONCAT('%', #{camp_nm},'%')
and b.pro_tg_tp = #{pro_tg_tp}
and b.pro_tp = #{pro_tp}
and (d.usr_nm like CONCAT('%', #{usr_nm},'%') or d.usr_log_id like CONCAT('%', #{usr_nm},'%'))
and a.CAMP_CH = #{camp_ch}
and b.min_start_dt >= #{st_dt}
and b.min_start_dt <= date_add(#{end_dt}, interval 1 day)

SELECT a.seq As seq ,b.PRO_ID AS pro_id , b.PRO_NM AS pro_nm , a.CAMP_ID AS camp_id , a.CAMP_NM AS camp_nm , b.PRO_ST AS pro_st , b.min_start_dt as start_dt , a.cont_id AS cont_id , case when lst.msg_tp Like 'DMCH21%' then json_extract(lst.cont_sub, '$.title1') ELSE lst.cont_sub END AS cont_sub , lst.cont_top_body AS cont_top_body , c.cd_nm as pro_st_nm , a.CAMP_CH AS camp_ch -- 채널 , a.TOTAL_CNT AS total_cnt , a.SUC_CNT AS suc_cnt , IFNULL(a.OPEN_CNT,0) AS open_cnt , IFNULL(a.CLICK_CNT,0) AS click_cnt FROM tblmire_camp_mst a INNER JOIN tblmicp_program b ON a.PRO_ID = b.PRO_ID INNER JOIN tblmi_comm_cd AS c ON c.grp_id = 'COMST' and b.PRO_ST = c.CD_ID LEFT JOIN tblmicp_cont_lst AS lst ON a.cont_id = lst.cont_cd WHERE -- b.pro_st = '04' AND a.usr_grp_cd =#{usr_grp_cd} AND a.seq IN
#{item}
GROUP BY a.seq ORDER BY a.REG_DT DESC

SELECT hst.pro_id , hst.camp_id , send_rst_tp , send_rst_det , sum(hst.SEND_CNT) AS send_cnt , comm.cd_val AS cd_val , comm.cd_desc AS cd_desc , comm.cd_desc AS cd_desc , comm.par_nm AS bounce_cate FROM tblmire_send_hst AS hst LEFT JOIN tblmire_camp_mst AS m ON m.pro_id = hst.pro_id AND m.camp_id = hst.camp_id LEFT JOIN tblmi_comm_cd AS comm ON comm.grp_id = 'SENDRESULT' AND comm.CD_NM = hst.m_server AND comm.cd_id = hst.send_rst_det AND comm.par_id = hst.send_rst_tp
and m.seq IN
#{item}
and hst.send_rst =#{send_rst}
and hst.usr_grp_cd =#{usr_grp_cd}
GROUP BY MSG_TP,SEND_RST_DET

